{
  "name": "get_interface_status",
  "description": "Read-only. Returns operational status, access VLAN and error counters for one switch interface. It never changes configuration.",
  "parameters": {
    "type": "object",
    "properties": {
      "device": {
        "type": "string",
        "description": "Device hostname from the inventory, for example sw-branch1.example.com"
      },
      "interface": {
        "type": "string",
        "description": "Full interface name, for example GigabitEthernet1/0/12",
        "pattern": "^(GigabitEthernet|TenGigabitEthernet)[0-9/]+$"
      }
    },
    "required": ["device", "interface"],
    "additionalProperties": false
  }
}

